            return Node('callstmt',line, expr=expr)
    def parse_funcbody(self, is_method):
        line=self.cur.line
        self.expect('(')
        params=[]; vararg=False
        if self.cur.type!=')':
            while True:
                if self.cur.type=='name': params.append(self.advance().value)
                elif self.cur.type=='...': self.advance(); vararg=True; break
                else: self.error_expected('name')
                if not self.check(','): break
                # after comma could be ...
                if self.cur.type=='...': self.advance(); vararg=True; break
        self.expect(')')
        if is_method: params=['self']+params
        # new function context
        old_loops=self.functions[-1]['loops'] if self.functions else 0
        finfo={'vararg':vararg,'loops':0,'gotos':[],'labels':set()}
        self.functions.append(finfo)
        body=self.parse_block()
        endline=self.cur.line
        self.expect('end')
        self.validate_gotos(finfo)
        self.functions.pop()
        proto=Node('funcbody',line, params=params, vararg=vararg, body=body, linedefined=line, lastlinedefined=endline, is_method=is_method)
        return Node('function',line, proto=proto)
    def parse_exprlist(self):
        exprs=[self.parse_expr()]
        while self.check(','): exprs.append(self.parse_expr())
        return exprs
    def parse_expr(self):
        return self.parse_subexpr(0)
    def parse_subexpr(self, limit):
        t=self.cur
        if t.type in ('not','-','#'):
            op=self.advance().type; line=t.line
            operand=self.parse_subexpr(8)
            left=Node('unop',line, op=op, expr=operand)
        else:
            left=self.parse_simple_expr()
        while True:
            op=self.cur.type
            if op not in BINPRI: break
            lpri, rpri=BINPRI[op]
            if lpri<=limit: break
            line=self.advance().line
            right=self.parse_subexpr(rpri)
            left=Node('binop',line, op=op, left=left, right=right)
        return left
    def parse_simple_expr(self):
        t=self.cur
        if t.type=='nil': self.advance(); return Node('nil',t.line)
        if t.type=='true': self.advance(); return Node('bool',t.line, value=True)
        if t.type=='false': self.advance(); return Node('bool',t.line, value=False)
        if t.type=='number': self.advance(); return Node('number',t.line, value=t.value)
        if t.type=='string': self.advance(); return Node('string',t.line, value=t.value)
        if t.type=='...':
            self.advance()
            if not self.functions[-1]['vararg']:
                raise SyntaxErr("cannot use '...' outside a vararg function", t.line, self.chunk_display)
            return Node('vararg',t.line)
        if t.type=='function':
            self.advance(); return self.parse_funcbody(False)
        if t.type=='{':
            return self.parse_table()
        # prefix
        return self.parse_suffixed_expr()
    def parse_table(self):
        line=self.expect('{').line
        fields=[] # list of (kind, keyexpr or None, valuexpr)
        while self.cur.type!='}':
            if self.cur.type=='[':
                self.advance(); k=self.parse_expr(); self.expect(']'); self.expect('='); v=self.parse_expr(); fields.append(('key',k,v))
            elif self.cur.type=='name' and self.peek_next_is('='):
                name_tok=self.advance(); self.advance() # =
                v=self.parse_expr(); fields.append(('name',name_tok.value,v))
            else:
                v=self.parse_expr(); fields.append(('list',None,v))
            if self.cur.type in (',',';'): self.advance()
            elif self.cur.type!='}':
                self.error_expected('}')
        self.expect('}')
        return Node('table',line, fields=fields)
    def peek_next_is(self, typ):
        # lexer only has current; we need lookahead hack: save state
        save=(self.lex.pos, self.lex.line, self.lex.cur)
        self.lex.next_token(); nxt=self.lex.cur.type
        # restore
        self.lex.pos, self.lex.line, self.lex.cur = save
        return nxt==typ
    def parse_suffixed_expr(self):
        # primary
        t=self.cur
        if t.type=='name':
            self.advance(); expr=Node('var',t.line, name=t.value)
        elif t.type=='(':
            line=self.advance().line; e=self.parse_expr(); self.expect(')'); expr=Node('paren',line, expr=e)
        else:
            raise SyntaxErr(f"unexpected symbol near '{self.token_text(t)}'", t.line, self.chunk_display)
        while True:
            ct=self.cur
            if ct.type=='.':
                self.advance(); fn=self.expect('name'); expr=Node('index',fn.line, obj=expr, key=Node('string',fn.line, value=S(fn.value)), field=fn.value)
            elif ct.type=='[':
                line=self.advance().line; k=self.parse_expr(); self.expect(']'); expr=Node('index',line, obj=expr, key=k)
            elif ct.type==':':
                line=self.advance().line; fn=self.expect('name')
                args=self.parse_call_args()
                expr=Node('mcall',line, obj=expr, name=fn.value, args=args)
            elif ct.type in ('(','string','{'):
                args=self.parse_call_args()
                expr=Node('call',ct.line, func=expr, args=args)
            else:
                break
        return expr
    def parse_call_args(self):
        t=self.cur
        if t.type=='(':
            self.advance()
            args=[]
            if self.cur.type!=')': args=self.parse_exprlist()
            self.expect(')')
            return args
        if t.type=='string':
            self.advance(); return [Node('string',t.line, value=t.value)]
        if t.type=='{':
            return [self.parse_table()]
        self.error_expected('(')

