# ---------- Lexer / Parser ----------
KEYWORDS={'and','break','do','else','elseif','end','false','for','function','goto','if','in','local','nil','not','or','repeat','return','then','true','until','while'}

def display_chunkname(chunkname):
    # chunkname: bytes
    if chunkname is None: return b"[?]"
    if isinstance(chunkname, str): chunkname=S(chunkname)
    if chunkname.startswith(b'='):
        return chunkname[1:]
    if chunkname.startswith(b'@'):
        return chunkname[1:]
    # for string chunks
    # If it's plain name like "(command line)" or "stdin" ??? Lua treats chunkname as file if @, descriptive if =, else string
    # Our internal chunknames: we pass display directly for main chunks and source for load
    # Caller sets chunkname_is_string flag separately via prefix marker? use convention: internal names stored as bytes display unless loadstring.
    return chunkname

class SyntaxErr(Exception):
    def __init__(self, msg, line=None, chunk_display=None):
        self.msg=msg; self.line=line; self.chunk_display=chunk_display
    def full(self):
        if self.chunk_display is not None:
            return self.chunk_display + b":" + str(self.line).encode() + b": " + S(self.msg)
        return S(self.msg)

class Token:
    __slots__=('type','value','line')
    def __init__(self,t,v,l): self.type=t; self.value=v; self.line=l
    def __repr__(self): return f"Tok({self.type},{self.value!r},{self.line})"

class Lexer:
    def __init__(self, src_bytes, chunk_display):
        # src_bytes bytes
        if src_bytes.startswith(b'\xef\xbb\xbf'):
            src_bytes=src_bytes[3:]
        # Shebang first line handled by caller? Lua: if first char '#', skip first line
        if src_bytes.startswith(b'#'):
            idx=src_bytes.find(b'\n')
            if idx==-1: src_bytes=b''
            else: src_bytes=src_bytes[idx:]
        self.s=src_bytes.decode('latin-1')
        self.pos=0
        self.line=1
        self.chunk_display=chunk_display
        self.cur=None
        self.next_token()
    def err(self, msg, line=None):
        raise SyntaxErr(msg, line if line is not None else self.line, self.chunk_display)
    def peek_char(self, off=0):
        p=self.pos+off
        return self.s[p] if p < len(self.s) else ''
    def advance(self):
        ch=self.s[self.pos]; self.pos+=1
        if ch=='\n': self.line+=1
        return ch
    def skip(self):
        while self.pos < len(self.s):
            ch=self.s[self.pos]
            if ch in ' \t\r\f\v':
                self.pos+=1
            elif ch=='\n':
                self.pos+=1; self.line+=1
            elif ch=='-' and self.peek_char(1)=='-':
                # comment
                self.pos+=2
                # long?
                if self.pos < len(self.s) and self.s[self.pos]=='[':
                    # check long bracket
                    j=self.pos+1
                    eq=0
                    while j < len(self.s) and self.s[j]=='=': eq+=1; j+=1
                    if j < len(self.s) and self.s[j]=='[':
                        # long comment
                        self.pos=j+1
                        # skip content to closing
                        close=']'+'='*eq+']'
                        # handle first newline
                        while self.pos < len(self.s):
                            if self.s.startswith(close, self.pos):
                                self.pos+=len(close); break
                            if self.s[self.pos]=='\n': self.line+=1
                            self.pos+=1
                        else:
                            self.err("unfinished long comment")
                        continue
                # line comment
                while self.pos < len(self.s) and self.s[self.pos]!='\n':
                    self.pos+=1
            else:
                break
    def read_long_string(self, eq, start_line):
        # pos after opening [[
        # skip first newline
        if self.pos < len(self.s) and self.s[self.pos]=='\r':
            self.pos+=1
            if self.pos < len(self.s) and self.s[self.pos]=='\n': self.pos+=1; self.line+=1
            # treat as newline? Lua skips first newline
        elif self.pos < len(self.s) and self.s[self.pos]=='\n':
            self.pos+=1; self.line+=1
        close=']'+'='*eq+']'
        start=self.pos
        while self.pos < len(self.s):
            if self.s.startswith(close, self.pos):
                content=self.s[start:self.pos]
                self.pos+=len(close)
                return content
            if self.s[self.pos]=='\n': self.line+=1
            self.pos+=1
        self.err("unfinished long string", start_line)
    def check_long_bracket(self):
        # current char '[' ; return eq or -1
        j=self.pos+1; eq=0
        while j < len(self.s) and self.s[j]=='=': eq+=1; j+=1
        if j < len(self.s) and self.s[j]=='[':
            return eq
        return -1
    def next_token(self):
        self.skip()
        line=self.line
        if self.pos>=len(self.s):
            self.cur=Token('eof',None,line); return self.cur
        ch=self.s[self.pos]
        # names
        if ch.isalpha() or ch=='_' or ord(ch)>=128:
            start=self.pos
            while self.pos < len(self.s) and (self.s[self.pos].isalnum() or self.s[self.pos]=='_' or ord(self.s[self.pos])>=128):
                self.pos+=1
            word=self.s[start:self.pos]
            if word in KEYWORDS:
                self.cur=Token(word,word,line)
            else:
                self.cur=Token('name',word,line)
            return self.cur
        # numbers
        if ch.isdigit() or (ch=='.' and self.peek_char(1).isdigit()):
            start=self.pos
            # Lua reads number: consume alnum . and signs after e/E/p/P
            # Simplistic
            # handle hex?
            while self.pos < len(self.s):
                c=self.s[self.pos]
                if c.isalnum() or c=='.' or c=='_':
                    prev = self.s[self.pos-1] if self.pos>start else ''
                    self.pos+=1
                    # exponent sign
                    if c in 'eEpP' and self.pos < len(self.s) and self.s[self.pos] in '+-':
                        self.pos+=1
                    continue
                elif c in '+-' and self.pos>start and self.s[self.pos-1] in 'eEpP':
                    self.pos+=1; continue
                else:
                    break
            text=self.s[start:self.pos]
            val=str_to_num_bytes(text.encode('latin-1'))
            if val is None:
                self.err(f"malformed number near '{text}'", line)
            self.cur=Token('number',val,line)
            self.cur.value=val
            # store text also? use token value float; keep in separate attr via ... use token type number value float
            return self.cur
        # strings
        if ch=='"' or ch=="'":
            quote=ch; self.pos+=1
            out_bytes=bytearray()
            # We'll build Python str latin1 then encode
            out_chars=[]
            while True:
                if self.pos>=len(self.s):
                    self.err(f"unfinished string near '<eof>'", line)
                c=self.s[self.pos]
                if c==quote:
                    self.pos+=1; break
                if c=='\n' or c=='\r':
                    self.err("unfinished string", line)
                if c=='\\':
                    self.pos+=1
                    if self.pos>=len(self.s): self.err("unfinished string", line)
                    e=self.s[self.pos]
                    if e=='\n':
                        out_chars.append('\n'); self.pos+=1; self.line+=1
                    elif e=='\r':
                        self.pos+=1
                        if self.pos < len(self.s) and self.s[self.pos]=='\n': self.pos+=1
                        out_chars.append('\n'); self.line+=1
                    elif e=='a': out_chars.append('\a'); self.pos+=1
                    elif e=='b': out_chars.append('\b'); self.pos+=1
                    elif e=='f': out_chars.append('\f'); self.pos+=1
                    elif e=='n': out_chars.append('\n'); self.pos+=1
                    elif e=='r': out_chars.append('\r'); self.pos+=1
                    elif e=='t': out_chars.append('\t'); self.pos+=1
                    elif e=='v': out_chars.append('\v'); self.pos+=1
                    elif e=='\\': out_chars.append('\\'); self.pos+=1
                    elif e=='"': out_chars.append('"'); self.pos+=1
                    elif e=="'": out_chars.append("'"); self.pos+=1
                    elif e.isdigit():
                        num=0; cnt=0
                        while cnt<3 and self.pos < len(self.s) and self.s[self.pos].isdigit():
                            num=num*10+int(self.s[self.pos]); self.pos+=1; cnt+=1
                        if num>255: self.err("escape sequence too large", line)
                        out_chars.append(chr(num))
                    elif e=='x':
                        self.pos+=1
                        hexs=''
                        for _ in range(2):
                            if self.pos < len(self.s) and self.s[self.pos] in '0123456789abcdefABCDEF':
                                hexs+=self.s[self.pos]; self.pos+=1
                            else: self.err("hexadecimal digit expected", line)
                        out_chars.append(chr(int(hexs,16)))
                    elif e=='z':
                        self.pos+=1
                        # skip whitespace incl newlines
                        while self.pos < len(self.s) and self.s[self.pos] in ' \t\r\f\v\n':
                            if self.s[self.pos]=='\n': self.line+=1
                            self.pos+=1
                    elif e=='u':
                        self.pos+=1
                        if self.pos>=len(self.s) or self.s[self.pos]!='{': self.err("missing '{' in \\u escape", line) # approx
                        self.pos+=1
                        hexs=''
                        while self.pos < len(self.s) and self.s[self.pos]!='}':
                            hexs+=self.s[self.pos]; self.pos+=1
                        if self.pos>=len(self.s): self.err("missing '}'", line)
                        self.pos+=1
                        try: cp=int(hexs,16)
                        except: self.err("bad \\u escape", line)
                        # encode UTF-8 as latin1 chars?
                        # produce unicode char if cp <=0xFF? But Lua encodes UTF-8 bytes.
                        # Represent as bytes: we need out as bytes.
                        # We'll append encoded bytes as latin1 chars
                        utf8=chr(cp).encode('utf-8', errors='surrogatepass')
                        for b in utf8: out_chars.append(chr(b))
                    else:
                        self.err(f"invalid escape sequence near '\\{e}'", line)
                    continue
                else:
                    out_chars.append(c); self.pos+=1
            text=''.join(out_chars)
            b=text.encode('latin-1', errors='surrogateescape') if all(ord(c)<=255 for c in text) else text.encode('utf-8')
            # Actually chars from \u already utf8 bytes as latin1, encoding latin1 restores.
            try: b=text.encode('latin-1')
            except: b=text.encode('utf-8')
            self.cur=Token('string',b,line); return self.cur
        if ch=='[':
            eq=self.check_long_bracket()
            if eq>=0:
                self.pos+=1
                # consume ='s and [
                while self.pos < len(self.s) and self.s[self.pos]=='=': self.pos+=1
                self.pos+=1 # second [
                content=self.read_long_string(eq, line)
                b=content.encode('latin-1')
                self.cur=Token('string',b,line); return self.cur
        # symbols
        three=self.s[self.pos:self.pos+3]
        two=self.s[self.pos:self.pos+2]
        if three=='...':
            self.pos+=3; self.cur=Token('...','...',line); return self.cur
        if two in ('..','==','~=','<=','>=','::'):
            self.pos+=2; self.cur=Token(two,two,line); return self.cur
        if ch in '+-*/%^#=<>;:,.(){}[]':
            self.pos+=1; self.cur=Token(ch,ch,line); return self.cur
