        self.lex=Lexer(src_bytes, chunk_display)
        self.chunk_display=chunk_display
        self.functions=[] # stack of func info dicts for break/goto/vararg validation
    @property
    def cur(self): return self.lex.cur
    def advance(self):
        t=self.lex.cur; self.lex.next_token(); return t
    def expect(self, typ):
        if self.cur.type!=typ:
            self.error_expected(typ)
        return self.advance()
    def error_expected(self, typ):
        # messages similar Lua
        # mapping
        if typ=='end' or typ==')' or typ==']' or typ=='}' or typ=='then' or typ=='do' or typ=='until' or typ=='=' or typ=='(':
            msg=f"'{typ}' expected near '{self.token_text(self.cur)}'"
        elif typ=='name':
            msg=f"<name> expected near '{self.token_text(self.cur)}'"
        else:
            msg=f"'{typ}' expected near '{self.token_text(self.cur)}'"
        raise SyntaxErr(msg, self.cur.line, self.chunk_display)
    def token_text(self,t):
        if t.type=='eof': return "<eof>"
        if t.type=='string':
            # show ???
            return "<string>"
        if t.type=='number': return fmt_num(t.value)
        return str(t.value)
    def check(self, typ):
        if self.cur.type==typ: self.advance(); return True
        return False
    def parse(self):
        # main chunk is vararg function
        self.functions.append({'vararg':True,'loops':0,'gotos':[],'labels':set(),'func_depth':0})
        block=self.parse_block()
        if self.cur.type!='eof':
            raise SyntaxErr(f"unexpected symbol near '{self.token_text(self.cur)}'", self.cur.line, self.chunk_display)
        # validate gotos
        self.validate_gotos(self.functions[-1])
        self.functions.pop()
        proto=Node('funcbody',1, params=[], vararg=True, body=block, linedefined=0, lastlinedefined=self.lex.line)
        return proto
    def validate_gotos(self, finfo):
        for (name,line) in finfo['gotos']:
            if name not in finfo['labels']:
                raise SyntaxErr(f"no visible label '{name}' for <goto> at line {line}", line, self.chunk_display) # will adjust later based on probe
        # Note Lua message format checked later
    def parse_block(self):
        stmts=[]
        while self.cur.type not in ('end','else','elseif','until','eof'):
            if self.cur.type=='return':
                line=self.advance().line
                exprs=[]
                if self.cur.type not in ('end','else','elseif','until','eof',';'):
                    exprs=self.parse_exprlist()
                self.check(';')
                stmts.append(Node('return',line, exprs=exprs))
                # return must be last: if more statements, Lua will error on next parse loop? Actually parser expects block end.
                if self.cur.type not in ('end','else','elseif','until','eof'):
                    raise SyntaxErr(f"unexpected symbol near '{self.token_text(self.cur)}'", self.cur.line, self.chunk_display)
                break
            stmt=self.parse_statement()
            if stmt is not None:
                if isinstance(stmt, list): stmts.extend(stmt)
                else: stmts.append(stmt)
        return Node('block', stmts[0].line if stmts else self.cur.line, stmts=stmts)
    def parse_statement(self):
        t=self.cur
        if t.type==';':
            # In non-52compat, ;; is error but single ; as statement? Lua 5.1 allows ; as empty? test: chunk ";" earlier error unexpected symbol near ';' for -e ";" . That suggests semicolon alone not statement? But after statements, ; consumed elsewhere.
            raise SyntaxErr("unexpected symbol near ';'", t.line, self.chunk_display)
        if t.type=='do':
            line=self.advance().line; blk=self.parse_block(); self.expect('end'); return Node('do',line, body=blk)
        if t.type=='while':
            line=self.advance().line; cond=self.parse_expr(); self.expect('do')
            self.functions[-1]['loops']+=1
            blk=self.parse_block(); self.functions[-1]['loops']-=1
            self.expect('end'); return Node('while',line, cond=cond, body=blk)
        if t.type=='repeat':
            line=self.advance().line
            self.functions[-1]['loops']+=1
            blk=self.parse_block(); 
            # until is terminator
            self.expect('until'); cond=self.parse_expr(); self.functions[-1]['loops']-=1
            return Node('repeat',line, body=blk, cond=cond)
        if t.type=='if':
            line=self.advance().line
            cases=[]
            cond=self.parse_expr(); self.expect('then'); blk=self.parse_block(); cases.append((cond,blk))
            while self.cur.type=='elseif':
                self.advance(); c=self.parse_expr(); self.expect('then'); b=self.parse_block(); cases.append((c,b))
            elseblk=None
            if self.cur.type=='else':
                self.advance(); elseblk=self.parse_block()
            self.expect('end'); return Node('if',line, cases=cases, elseblk=elseblk)
        if t.type=='for':
            line=self.advance().line
            name=self.expect('name').value
            if self.cur.type=='=':
                self.advance(); start=self.parse_expr(); self.expect(','); stop=self.parse_expr()
                step=None
                if self.check(','): step=self.parse_expr()
                self.expect('do'); self.functions[-1]['loops']+=1; blk=self.parse_block(); self.functions[-1]['loops']-=1; self.expect('end')
                return Node('fornum',line, name=name, start=start, stop=stop, step=step, body=blk)
            else:
                names=[name]
                while self.check(','): names.append(self.expect('name').value)
                self.expect('in'); exprs=self.parse_exprlist(); self.expect('do')
                self.functions[-1]['loops']+=1; blk=self.parse_block(); self.functions[-1]['loops']-=1; self.expect('end')
                return Node('forin',line, names=names, exprs=exprs, body=blk)
        if t.type=='function':
            line=self.advance().line
            # funcname: name ('.' name)* (':' name)?
            base=self.expect('name'); base_node=Node('var',base.line, name=base.value)
            target=base_node; is_method=False
            while self.cur.type=='.':
                self.advance(); fn=self.expect('name'); target=Node('index',fn.line, obj=target, key=Node('string',fn.line, value=S(fn.value)))
            if self.cur.type==':':
                self.advance(); fn=self.expect('name'); target=Node('index',fn.line, obj=target, key=Node('string',fn.line, value=S(fn.value))); is_method=True
            func=self.parse_funcbody(is_method)
            # becomes assign target = func
            return Node('assign',line, targets=[target], exprs=[func], local=False)
        if t.type=='local':
            line=self.advance().line
            if self.cur.type=='function':
                self.advance(); name=self.expect('name'); func=self.parse_funcbody(False)
                return Node('localfunc',line, name=name.value, func=func)
            names=[]
            names.append(self.expect('name').value)
            while self.check(','): names.append(self.expect('name').value)
            exprs=[]
            if self.check('='): exprs=self.parse_exprlist()
            return Node('local',line, names=names, exprs=exprs)
        if t.type=='break':
            line=self.advance().line
            if self.functions[-1]['loops']==0:
                raise SyntaxErr("<break> not inside a loop", line, self.chunk_display) # approx later
            return Node('break',line)
        if t.type=='goto':
            # goto as statement if next token is name; note goto is keyword token in lexer, but local goto=... would have been parsed as ??? If token goto and next is '=', parser... Our lexer makes goto keyword, so "local goto" already failed in parse local expecting name.
            # LuaJIT allows goto as identifier in some contexts; need special handling in other parsers entries (handled elsewhere)
            line=self.advance().line; name=self.expect('name').value
            self.functions[-1]['gotos'].append((name,line))
            return Node('goto',line, name=name)
        if t.type=='::':
            line=self.advance().line; name=self.expect('name').value; self.expect('::')
            self.functions[-1]['labels'].add(name)
            return Node('label',line, name=name)
        # expression statement: assignment or call
        # parse suffixed expr
        line=t.line
        expr=self.parse_suffixed_expr()
        if self.cur.type in ('=',','):
            targets=[expr]
            while self.check(','): targets.append(self.parse_suffixed_expr())
            self.expect('='); exprs=self.parse_exprlist()
            # validate targets are var/index
            return Node('assign',line, targets=targets, exprs=exprs, local=False)
        else:
            # must be call
            if expr.kind not in ('call','mcall'):
                raise SyntaxErr(f"unexpected symbol near '{self.token_text(self.cur)}'", self.cur.line, self.chunk_display)
            return Node('callstmt',line, expr=expr)
    def parse_funcbody(self, is_method):
        line=self.cur.line
        self.expect('(')
        params=[]; vararg=False
        if self.cur.type!=')':
            while True:
                if self.cur.type=='name': params.append(self.advance().value)
                elif self.cur.type=='...': self.advance(); vararg=True; break
                else: self.error_expected('name')
                if not self.check(','): break
                # after comma could be ...
                if self.cur.type=='...': self.advance(); vararg=True; break
        self.expect(')')
        if is_method: params=['self']+params
        # new function context
        old_loops=self.functions[-1]['loops'] if self.functions else 0
        finfo={'vararg':vararg,'loops':0,'gotos':[],'labels':set()}
        self.functions.append(finfo)
        body=self.parse_block()
        endline=self.cur.line
        self.expect('end')
        self.validate_gotos(finfo)
        self.functions.pop()
        proto=Node('funcbody',line, params=params, vararg=vararg, body=body, linedefined=line, lastlinedefined=endline, is_method=is_method)
        return Node('function',line, proto=proto)
    def parse_exprlist(self):
        exprs=[self.parse_expr()]
        while self.check(','): exprs.append(self.parse_expr())
        return exprs
    def parse_expr(self):
        return self.parse_subexpr(0)
    def parse_subexpr(self, limit):
        t=self.cur
        if t.type in ('not','-','#'):
            op=self.advance().type; line=t.line
            operand=self.parse_subexpr(8)
            left=Node('unop',line, op=op, expr=operand)
        else:
            left=self.parse_simple_expr()
        while True:
            op=self.cur.type
            if op not in BINPRI: break
            lpri, rpri=BINPRI[op]
            if lpri<=limit: break
            line=self.advance().line
            right=self.parse_subexpr(rpri)
            left=Node('binop',line, op=op, left=left, right=right)
        return left
    def parse_simple_expr(self):
        t=self.cur
        if t.type=='nil': self.advance(); return Node('nil',t.line)
        if t.type=='true': self.advance(); return Node('bool',t.line, value=True)
        if t.type=='false': self.advance(); return Node('bool',t.line, value=False)
        if t.type=='number': self.advance(); return Node('number',t.line, value=t.value)
        if t.type=='string': self.advance(); return Node('string',t.line, value=t.value)
        if t.type=='...':
            self.advance()
            if not self.functions[-1]['vararg']:
                raise SyntaxErr("cannot use '...' outside a vararg function", t.line, self.chunk_display)
            return Node('vararg',t.line)
        if t.type=='function':
            self.advance(); return self.parse_funcbody(False)
        if t.type=='{':
            return self.parse_table()
        # prefix
        return self.parse_suffixed_expr()
    def parse_table(self):
        line=self.expect('{').line
        fields=[] # list of (kind, keyexpr or None, valuexpr)
        while self.cur.type!='}':
            if self.cur.type=='[':
                self.advance(); k=self.parse_expr(); self.expect(']'); self.expect('='); v=self.parse_expr(); fields.append(('key',k,v))
            elif self.cur.type=='name' and self.peek_next_is('='):
                name_tok=self.advance(); self.advance() # =
                v=self.parse_expr(); fields.append(('name',name_tok.value,v))
            else:
                v=self.parse_expr(); fields.append(('list',None,v))
            if self.cur.type in (',',';'): self.advance()
            elif self.cur.type!='}':
                self.error_expected('}')
        self.expect('}')
        return Node('table',line, fields=fields)
    def peek_next_is(self, typ):
        # lexer only has current; we need lookahead hack: save state
        save=(self.lex.pos, self.lex.line, self.lex.cur)
        self.lex.next_token(); nxt=self.lex.cur.type
        # restore
        self.lex.pos, self.lex.line, self.lex.cur = save
        return nxt==typ
    def parse_suffixed_expr(self):
        # primary
        t=self.cur
        if t.type=='name':
            self.advance(); expr=Node('var',t.line, name=t.value)
        elif t.type=='(':
            line=self.advance().line; e=self.parse_expr(); self.expect(')'); expr=Node('paren',line, expr=e)
        else:
            raise SyntaxErr(f"unexpected symbol near '{self.token_text(t)}'", t.line, self.chunk_display)
        while True:
            ct=self.cur
            if ct.type=='.':
                self.advance(); fn=self.expect('name'); expr=Node('index',fn.line, obj=expr, key=Node('string',fn.line, value=S(fn.value)), field=fn.value)
            elif ct.type=='[':
                line=self.advance().line; k=self.parse_expr(); self.expect(']'); expr=Node('index',line, obj=expr, key=k)
            elif ct.type==':':
                line=self.advance().line; fn=self.expect('name')
                args=self.parse_call_args()
                expr=Node('mcall',line, obj=expr, name=fn.value, args=args)
            elif ct.type in ('(','string','{'):
                args=self.parse_call_args()
                expr=Node('call',ct.line, func=expr, args=args)
            else:
                break
        return expr
    def parse_call_args(self):
        t=self.cur
        if t.type=='(':
            self.advance()
            args=[]
            if self.cur.type!=')': args=self.parse_exprlist()
            self.expect(')')
            return args
        if t.type=='string':
            self.advance(); return [Node('string',t.line, value=t.value)]
        if t.type=='{':
            return [self.parse_table()]
        self.error_expected('(')

