# ---------- Interpreter core ----------
class Frame:
    __slots__=('kind','func','proto','env','scopes','varargs','name','namewhat','chunk_display','chunkname','current_line','linedefined','lastlinedefined','is_main','up_scopes','locals_order','tail_name')
    def __init__(self, kind, func=None, proto=None, env=None):
        self.kind=kind; self.func=func; self.proto=proto; self.env=env
        self.scopes=[]; self.varargs=[]; self.name=None; self.namewhat=None
        self.chunk_display=b''; self.chunkname=b''; self.current_line=0
        self.linedefined=0; self.lastlinedefined=0; self.is_main=False
        self.up_scopes=[]; self.locals_order=[]; self.tail_name=None

class Interp:
    def __init__(self):
        self.tls=threading.local()
        self.globals=None
        self.registry=None
        self.string_mt=None
        self.number_mt=None; self.bool_mt=None; self.nil_mt=None
        self.loaded=None; self.preload=None
        self.jit_on=True
        self.jit_opts=set(['fold','cse','dce','fwd','dse','narrow','loop','abc','sink','fuse'])
        self.jit_params={'maxtrace':1000,'maxrecord':4000,'maxirconst':500,'maxside':100,'maxsnap':500,'hotloop':56,'hotexit':10,'tryside':4,'instunroll':4,'loopunroll':15,'callunroll':3,'recunroll':2,'maxcode':4096,'sizemcode':64,'maxmcode':2048} # some checked later
        self.hook_func=None; self.hook_mask=''; self.hook_count=0; self.hook_counter=0; self.in_hook=False
        self.stdin=None; self.stdout=None; self.stderr=None
        self.default_input=None; self.default_output=None
        self.prng_state=None
        self.progname="./executable"
        self.exit_code=0; self.exiting=False
        self.main_thread=LuaThread(is_main=True); self.main_thread.status="running"
        self.current_co=None
        self.gc_count_base=0
        self.debug_no_meta=False
    # stack mgmt
    def stack(self):
        if not hasattr(self.tls,'stack'): self.tls.stack=[]
        return self.tls.stack
    def cur_frame(self):
        st=self.stack(); return st[-1] if st else None
    def cur_lua_frame(self):
        for fr in reversed(self.stack()):
            if fr.kind=='lua': return fr
        return None
    def get_thread_obj(self):
        if hasattr(self.tls,'thread_obj') and self.tls.thread_obj is not None: return self.tls.thread_obj
        return self.main_thread
    # errors
    def loc_prefix(self, level=1):
        # level 1 = current lua function
        frames=[fr for fr in self.stack() if fr.kind=='lua']
        if len(frames)>=level:
            fr=frames[-level]
            return fr.chunk_display + b":" + str(fr.current_line).encode() + b": "
        return b""
    def make_error(self, value):
        e=LuaError(value)
        e.stack_snapshot=self.snapshot_stack()
        return e
    def error_str(self, msg_bytes, level=1):
        # msg with location prefix if level>0 and lua frame exists
        if level==0:
            e=LuaError(S(msg_bytes))
        else:
            frames=[fr for fr in self.stack() if fr.kind=='lua']
            if frames:
                # level 1: frame immediately ... For VM errors, current frame is caller.
                idx=len(frames)-level
                if idx<0: idx=0
                fr=frames[idx]
                full=fr.chunk_display + b":" + str(fr.current_line).encode() + b": " + S(msg_bytes)
            else:
                full=S(msg_bytes)
            e=LuaError(full)
        e.stack_snapshot=self.snapshot_stack()
        raise e
    def arg_error(self, idx, msg_bytes):
        # msg_bytes already like "(string expected, got nil)" or custom
        # find C frame on top, caller lua below it
        st=self.stack()
        cframe=None; caller=None
        for fr in reversed(st):
            if fr.kind=='c' and cframe is None:
                cframe=fr; continue
            if fr.kind=='lua': caller=fr; break
            if fr.kind=='c' and cframe is not None:
                # another C frame is caller context? Lua considers...
                caller=fr; break
        name=b"?"
        if cframe is not None:
            if cframe.name: name=S(cframe.name)
            elif isinstance(cframe.func, BuiltinFunction) and cframe.func.name: name=S(cframe.func.name)
        if caller is not None and caller.kind=='lua':
            full=caller.chunk_display + b":" + str(caller.current_line).encode() + b": bad argument #" + str(idx).encode() + b" to '" + name + b"' " + S(msg_bytes)
        elif caller is not None and caller.kind=='c':
