            full=b"bad argument #" + str(idx).encode() + b" to '?' " + S(msg_bytes)
        else:
            full=b"bad argument #" + str(idx).encode() + b" to '" + name + b"' " + S(msg_bytes)
        e=LuaError(full); e.stack_snapshot=self.snapshot_stack(); raise e
    def snapshot_stack(self):
        snap=[]
        for fr in self.stack():
            snap.append({'kind':fr.kind,'name':fr.name,'namewhat':fr.namewhat,'chunk_display':fr.chunk_display,'current_line':fr.current_line,'linedefined':fr.linedefined,'is_main':fr.is_main,'func':fr.func})
        return snap
    def format_traceback(self, snap):
        # snap bottom->top; output top first
        lines=[]
        if snap is None: snap=self.snapshot_stack()
        for fr in reversed(snap):
            if fr['kind']=='c':
                if fr.get('name'):
