        # field name
        fname=getattr(node,'field',None)
        if fname: return b"field '" + S(fname) + b"'"
        k=getattr(node,'key',None)
        if k is not None and k.kind=='string':
            return b"field '" + k.value + b"'"
        return None
    return None

def _err_attempt(interp, verb, v, desc):
    # verb bytes like b"perform arithmetic on"
    if desc:
        interp.error_str(b"attempt to " + verb + b" " + desc + b" (a " + S(lua_type(v)) + b" value)")
    else:
        interp.error_str(b"attempt to " + verb + b" a " + S(lua_type(v)) + b" value")

def _eval1(interp, node):
    res=_eval_multi_dispatch(interp, node, False)
    return res
def _eval_multi_dispatch(interp, node, want_multi):
    # returns single value if not want_multi, else list for multi-capable nodes handled by caller
    # This helper only used for single; multi handled in _eval_multi
    return _eval_single(interp, node)

def _eval_multi(interp, node):
    frame=interp.cur_lua_frame()
    if frame: frame.current_line=node.line
    if node.kind=='call':
        return _eval_call(interp, node)
    if node.kind=='mcall':
        return _eval_call(interp, node)
    if node.kind=='vararg':
        if frame: return list(frame.varargs)
        return []
    if node.kind=='paren':
        return [_eval_single(interp, node.expr)]
    return [_eval_single(interp, node)]

def _eval_exprlist(interp, exprs):
    out=[]
    for i,e in enumerate(exprs):
        if i==len(exprs)-1:
            out.extend(_eval_multi(interp, e))
        else:
            out.append(_eval_single(interp, e))
    return out

def _nameinfo_for(interp, frame, node):
    if node.kind=='var':
        if frame and interp.find_cell(frame, node.name) is not None:
            return ('local', node.name)
        return ('global', node.name)
    if node.kind=='index':
        fname=getattr(node,'field',None)
        if fname: return ('field', fname)
        k=getattr(node,'key',None)
        if k is not None and k.kind=='string':
            return ('field', k.value.decode('latin-1'))
        return (None,None)
    return (None,None)

def _eval_call(interp, node):
    frame=interp.cur_lua_frame()
    if frame: frame.current_line=node.line
    if node.kind=='mcall':
        obj=_eval_single(interp, node.obj)
        # get method
        fn=interp.get_index(obj, S(node.name), desc=None)
        args=[obj]+_eval_exprlist(interp, node.args)
        if not callable_lua(interp, fn):
            if fn is None:
                # attempt to call method error approximation
                interp.error_str(b"attempt to call method '" + S(node.name) + b"' (a nil value)")
            _err_attempt(interp, b"call method '"+S(node.name)+b"'", fn, None)
        return interp.call_value(fn, args, nameinfo=('method', node.name))
    else:
        fn=_eval_single(interp, node.func)
        args=_eval_exprlist(interp, node.args)
        ninfo=_nameinfo_for(interp, frame, node.func)
        if not callable_lua(interp, fn):
            desc=_describe_node(interp, frame, node.func)
            if desc:
                interp.error_str(b"attempt to call " + desc + b" (a " + S(lua_type(fn)) + b" value)")
            else:
                interp.error_str(b"attempt to call a " + S(lua_type(fn)) + b" value")
        return interp.call_value(fn, args, nameinfo=ninfo)

def _eval_single(interp, node):
    frame=interp.cur_lua_frame()
    if frame and node.line: frame.current_line=node.line
    k=node.kind
    if k=='nil': return None
    if k=='bool': return node.value
    if k=='number': return float(node.value)
    if k=='string': return node.value
    if k=='vararg':
        return frame.varargs[0] if frame and frame.varargs else None
    if k=='paren': return _eval_single(interp, node.expr)
    if k=='var':
        cell=interp.find_cell(frame, node.name) if frame else None
        if cell is not None: return cell.value
        env=frame.env if frame and frame.env is not None else interp.globals
        return interp.get_index(env, S(node.name))
    if k=='index':
        obj=_eval_single(interp, node.obj)
        key=_eval_single(interp, node.key)
        if isinstance(obj, CData):
            return cdata_get_index(interp, obj, key)
        desc=_describe_node(interp, frame, node.obj)
        return interp.get_index(obj, key, desc=desc)
    if k=='function':
        proto=node.proto
        # capture scopes snapshot
        captured=[]
        if frame: captured=[dict(s) for s in frame.scopes]
        fn=LuaFunction(proto, frame.env if frame else interp.globals, captured)
        return fn
    if k=='table':
        tbl=LuaTable()
        list_idx=1
        for idx, (fkind, fkey, fval) in enumerate(node.fields):
            is_last=(idx==len(node.fields)-1)
            if fkind=='list':
                if is_last:
                    vals=_eval_multi(interp, fval)
                else:
                    vals=[_eval_single(interp, fval)]
                for v in vals:
                    tbl.rawset(float(list_idx), v); list_idx+=1
            elif fkind=='name':
                v=_eval_single(interp, fval)
                tbl.rawset(S(fkey), v)
            else: # key
                kk=_eval_single(interp, fkey); v=_eval_single(interp, fval)
                # rawset raises for nil/nan but Lua constructor errors same messages without location? error_str adds loc via rawset LuaError plain
                try:
                    tbl.rawset(kk, v)
                except LuaError as e:
                    if e.stack_snapshot is None:
                        # add location prefix?
                        # Constructor errors in Lua: "table index is nil" without prefix? It is lua error via rawset? Testing later.
                        pass
                    raise
        return tbl
    if k in ('call','mcall'):
        res=_eval_call(interp, node)
        return res[0] if res else None
    if k=='unop':
        v=_eval_single(interp, node.expr)
        if node.op=='not':
            return (v is None or v is False)
        if node.op=='-':
            num=to_lua_num(v)
            if num is not None: return -num
            mm=interp.metamethod(v,'__unm')
            if mm is not None:
                r=interp.call_value(mm,[v],nameinfo=('metamethod','__unm')); return r[0] if r else None
            desc=_describe_node(interp, frame, node.expr)
            _err_attempt(interp, b"perform arithmetic on", v, desc)
        if node.op=='#':
            return _len_value(interp, v, node)
    if k=='binop':
        op=node.op
        if op=='and':
            l=_eval_single(interp, node.left)
            if l is None or l is False: return l
            return _eval_single(interp, node.right)
        if op=='or':
            l=_eval_single(interp, node.left)
            if not (l is None or l is False): return l
            return _eval_single(interp, node.right)
        # other ops
        l=_eval_single(interp, node.left); r=_eval_single(interp, node.right)
        if op=='==': return _eq_value(interp, l, r)
        if op=='~=': return not _eq_value(interp, l, r)
        if op in ('<','<=','>','>='):
            return _compare(interp, op, l, r, node)
        if op=='..':
            # convert
            ls = l if isinstance(l,bytes) else (fmt_num(l).encode() if is_num(l) else None)
            rs = r if isinstance(r,bytes) else (fmt_num(r).encode() if is_num(r) else None)
            if ls is not None and rs is not None: return ls+rs
            # metamethod __concat check first then second
            for operand in (l,r):
                mm=interp.metamethod(operand,'__concat')
                if mm is not None:
                    res=interp.call_value(mm,[l,r],nameinfo=('metamethod','__concat')); return res[0] if res else None
            bad = l if ls is None else r
            badnode = node.left if ls is None else node.right
            desc=_describe_node(interp, frame, badnode)
            _err_attempt(interp, b"concatenate", bad, desc)
        # arithmetic
        return _arith(interp, op, l, r, node)
    raise Exception(f"unknown expr {k}")

def _len_value(interp, v, node=None):
    if isinstance(v, bytes): return float(len(v))
    if isinstance(v, LuaTable):
        # __len not for tables in this build (no 52 compat), but strings? userdata only
        return float(v.rawlen_border())
    if isinstance(v, CData):
        return cdata_len(interp, v)
    mm=interp.metamethod(v,'__len')
    if mm is not None:
        r=interp.call_value(mm,[v],nameinfo=('metamethod','__len')); return r[0] if r else None
    frame=interp.cur_lua_frame()
    desc=_describe_node(interp, frame, node.expr) if node and node.kind=='unop' else None
    if desc:
        interp.error_str(b"attempt to get length of " + desc + b" (a " + S(lua_type(v)) + b" value)")
    interp.error_str(b"attempt to get length of a " + S(lua_type(v)) + b" value")

_ARITH_META={'+':'__add','-':'__sub','*':'__mul','/':'__div','%':'__mod','^':'__pow'}
def _arith(interp, op, l, r, node):
    ln=to_lua_num(l); rn=to_lua_num(r)
    if ln is not None and rn is not None:
        try:
            if op=='+': return ln+rn
            if op=='-': return ln-rn
            if op=='*': return ln*rn
            if op=='/':
                # Lua division by zero yields inf/nan
                if rn==0:
                    if ln==0: return math.nan
                    return math.copysign(math.inf, ln) * (1 if math.copysign(1,rn)>0 else -1) if False else (math.inf if (ln>0)==(math.copysign(1,rn)>0) else -math.inf)
                return ln/rn
            if op=='%':
                # Lua modulo: a - floor(a/b)*b
                if rn==0: return math.nan
                return ln - math.floor(ln/rn)*rn
            if op=='^':
                # pow handling overflow etc
                try: return math.pow(ln, rn)
                except OverflowError: return math.inf
                except ValueError:
                    # e.g. (-1)^0.5 = nan in C pow
                    return math.nan
        except Exception:
            return math.nan
    # CData arithmetic
    if isinstance(l, CData) or isinstance(r, CData):
        res=cdata_arith(interp, op, l, r)
        if res is not _sentinel: return res
    meta=_ARITH_META.get(op)
    if meta:
        for operand in (l,r):
            mm=interp.metamethod(operand, meta)
            if mm is not None:
                res=interp.call_value(mm,[l,r],nameinfo=('metamethod',meta)); return res[0] if res else None
    frame=interp.cur_lua_frame()
    # Determine bad operand: first that is not numeric (and not string numeric)
    if ln is None: bad=l; badnode=node.left if node else None
    else: bad=r; badnode=node.right if node else None
    desc=_describe_node(interp, frame, badnode) if badnode else None
    _err_attempt(interp, b"perform arithmetic on", bad, desc)

def _eq_value(interp, l, r):
    # cdata
    if isinstance(l, CData) or isinstance(r, CData):
        return cdata_eq(interp, l, r)
    if lua_type(l)!=lua_type(r):
        # number int/float both number
        return False
    if l is None or r is None: return l is r
    if isinstance(l, bool) or isinstance(r, bool): return l==r
    if is_num(l) and is_num(r): return float(l)==float(r)
    if isinstance(l, bytes): return l==r
    if l is r: return True
    # tables/userdata with __eq
    if isinstance(l, (LuaTable, LuaUserdata)) and type(l)==type(r):
        mt1=interp.getmt_raw(l); mt2=interp.getmt_raw(r)
        if mt1 is not None and mt1 is mt2:
            mm=None
            if isinstance(mt1, LuaTable): mm=mt1.rawget(b'__eq')
            if mm is not None:
                res=interp.call_value(mm,[l,r],nameinfo=('metamethod','__eq')); return bool(res and not (res[0] is None or res[0] is False))
    return False

def _compare(interp, op, l, r, node):
    if is_num(l) and is_num(r):
        a=float(l); b=float(r)
        if op=='<': return a<b
        if op=='<=': return a<=b
        if op=='>': return a>b
        if op=='>=': return a>=b
    if isinstance(l,bytes) and isinstance(r,bytes):
        if op=='<': return l<r
        if op=='<=': return l<=r
        if op=='>': return l>r
        if op=='>=': return l>=r
    if isinstance(l,CData) and isinstance(r,CData):
        res=cdata_compare(interp, op, l, r)
        if res is not _sentinel: return res
    # metamethods: only if same type (?) Lua 5.1: try lt/le
    if lua_type(l)==lua_type(r):
        meta='__lt' if op in ('<','>') else '__le'
        # if no __le but __lt, use negation fallback later
        mm=None
        for operand in (l,r):
            cand=interp.metamethod(operand, meta)
            if cand is not None: mm=cand; break
        if mm is not None:
            a,b=(l,r) if op in ('<','<=') else (r,l)
            res=interp.call_value(mm,[a,b],nameinfo=('metamethod',meta)); return not (not res or res[0] is None or res[0] is False)
        if op in ('<=','>='):
            # use __lt fallback
            mm=None
            for operand in (l,r):
                cand=interp.metamethod(operand,'__lt')
                if cand is not None: mm=cand; break
            if mm is not None:
                a,b=(r,l) if op=='<=' else (l,r)  # a<=b is not (b<a); a>=b is not (a<b?) Wait compute: a<=b -> not(b<a), a>=b -> not(a<b)
                # above mapping wrong; do explicit
                if op=='<=':
                    res=interp.call_value(mm,[r,l],nameinfo=('metamethod','__lt'))
                else:
                    res=interp.call_value(mm,[l,r],nameinfo=('metamethod','__lt'))
                return (not res or res[0] is None or res[0] is False)
    # errors
    if lua_type(l)!=lua_type(r):
        interp.error_str(b"attempt to compare " + S(lua_type(l)) + b" with " + S(lua_type(r)))
    else:
        interp.error_str(b"attempt to compare two " + S(lua_type(l)) + b" values")

# Statement execution
def _exec_block(interp, block):
    frame=interp.cur_lua_frame()
    frame.scopes.append({})
    try:
        _exec_stmt_list(interp, block)
    finally:
        frame.scopes.pop()

def _exec_stmt_list(interp, block):
    frame=interp.cur_lua_frame()
    stmts=block.stmts
    labels={}
    for i,st in enumerate(stmts):
        if st.kind=='label': labels[st.name]=i
    i=0
    while i < len(stmts):
        st=stmts[i]
        if frame: frame.current_line=st.line
        # line hook
        if interp.hook_func and 'l' in interp.hook_mask and not interp.in_hook:
            interp.call_hook('line', st.line)
        try:
            _exec_stmt(interp, st)
        except GotoExc as g:
            if g.name in labels:
                i=labels[g.name]+1
                continue
            raise
        i+=1

def _exec_stmt(interp, st):
    frame=interp.cur_lua_frame()
    if frame: frame.current_line=st.line
    k=st.kind
    if k=='label': return
    if k=='goto': raise GotoExc(st.name)
    if k=='break': raise BreakExc()
    if k=='return':
        # tail call optimization
        if len(st.exprs)==1 and st.exprs[0].kind in ('call','mcall'):
            node=st.exprs[0]
            # evaluate fn and args like _eval_call but raise TailCall
            if node.kind=='mcall':
                obj=_eval_single(interp, node.obj)
                fn=interp.get_index(obj, S(node.name))
                args=[obj]+_eval_exprlist(interp, node.args)
                raise TailCallExc(fn, args, ('method', node.name))
            else:
                fn=_eval_single(interp, node.func)
                args=_eval_exprlist(interp, node.args)
                ninfo=_nameinfo_for(interp, frame, node.func)
                raise TailCallExc(fn, args, ninfo)
        vals=_eval_exprlist(interp, st.exprs) if st.exprs else []
        raise ReturnExc(vals)
    if k=='do':
        _exec_block(interp, st.body); return
    if k=='while':
        while True:
            cond=_eval_single(interp, st.cond)
            if cond is None or cond is False: break
            try: _exec_block(interp, st.body)
            except BreakExc: break
        return
    if k=='repeat':
        # push scope combining body
        frame.scopes.append({})
        try:
            while True:
                try: _exec_stmt_list(interp, st.body)
                except BreakExc: break
                cond=_eval_single(interp, st.cond)
                if not (cond is None or cond is False): break
        finally:
            frame.scopes.pop()
        return
    if k=='if':
        for cond, blk in st.cases:
            v=_eval_single(interp, cond)
            if not (v is None or v is False):
                _exec_block(interp, blk); return
        if st.elseblk: _exec_block(interp, st.elseblk)
        return
    if k=='fornum':
        startv=to_lua_num(_eval_single(interp, st.start))
        if startv is None: interp.error_str(b"'for' initial value must be a number")
        stopv=to_lua_num(_eval_single(interp, st.stop))
        if stopv is None: interp.error_str(b"'for' limit must be a number")
        stepv=1.0
        if st.step is not None:
            stepv=to_lua_num(_eval_single(interp, st.step))
            if stepv is None: interp.error_str(b"'for' step must be a number")
        var=startv
        while True:
            if stepv>0:
                if not (var<=stopv): break
            elif stepv<0:
                if not (var>=stopv): break
            else:
                # step 0: original loops forever unless condition? Actually with step0 and start<=limit it infinite. We'll loop (body may break)
                if not (var<=stopv if True else False):
                    # LuaJIT: for with step 0? It will infinite if var <= limit. emulate: proceed
                    pass
                # If start > stop and step 0? In Lua, loop ??? step 0 positive direction check? treat as var<=stop
                if var>stopv: break
            cell=Cell(var)
            frame.scopes.append({st.name:cell})
            try:
                try: _exec_block(interp, st.body)
                except BreakExc: 
                    frame.scopes.pop(); break
            finally:
                # if not already popped in break path, need careful: we popped inside except, so track
                # Simpler: check if scope still present? We used try/finally plus pop in except double pops.
                # To avoid, we rework: removed finally pop below by flag
                pass
            # pop loop scope if still on stack top ??? The exec_block pushed/popped its own; loop scope is top now unless break popped it
            # Detect: if scopes and st.name in scopes[-1] maybe loop scope; pop it
            if frame.scopes and st.name in frame.scopes[-1]:
                frame.scopes.pop()
            # increment using internal var (not cell as closures may have modified? loop var assignments don't affect iteration in Lua)
            var = var + stepv
            # safeguard for step 0 infinite handled by user break
        return
    if k=='forin':
        vals=_eval_exprlist(interp, st.exprs)
        while len(vals)<3: vals.append(None)
        itf, state, control = vals[0], vals[1], vals[2]
        while True:
            if not callable_lua(interp, itf):
                # error for generic for: attempt to call a ...? Actually Lua checks ??? If iterator not callable, error on call
                # Mimic call error
                interp.call_value(itf, [state, control])  # will error
            res=interp.call_value(itf, [state, control])
            if not res or res[0] is None: break
            control=res[0]
            scope={}
            for i,name in enumerate(st.names):
                scope[name]=Cell(res[i] if i < len(res) else None)
            frame.scopes.append(scope)
            broke=False
            try: _exec_block(interp, st.body)
            except BreakExc: broke=True
            frame.scopes.pop()
            if broke: break
        return
    if k=='local':
        vals=_eval_exprlist(interp, st.exprs) if st.exprs else []
        scope=frame.scopes[-1]
        for i,name in enumerate(st.names):
            scope[name]=Cell(vals[i] if i < len(vals) else None)
        return
    if k=='localfunc':
        scope=frame.scopes[-1]
        cell=Cell(None); scope[st.name]=cell
        fn=_eval_single(interp, st.func)  # function node
        cell.value=fn
        return
    if k=='assign':
        # prepare targets
        targets=[]
        for tgt in st.targets:
            if tgt.kind=='var':
                cell=interp.find_cell(frame, tgt.name)
                targets.append(('var', tgt.name, cell))
            elif tgt.kind=='index':
                obj=_eval_single(interp, tgt.obj); key=_eval_single(interp, tgt.key)
                targets.append(('index', obj, key, tgt))
            else:
                interp.error_str(b"cannot assign")
        vals=_eval_exprlist(interp, st.exprs) if st.exprs else []
        for i,tgt in enumerate(targets):
            v=vals[i] if i < len(vals) else None
            if tgt[0]=='var':
                _,name,cell=tgt
                if cell is not None: cell.value=v
                else:
                    env=frame.env if frame.env else interp.globals
                    interp.set_index(env, S(name), v)
            else:
                _,obj,key,node=tgt
                if isinstance(obj, CData):
                    cdata_set_index(interp, obj, key, v)
                else:
                    desc=_describe_node(interp, frame, node.obj)
                    interp.set_index(obj, key, v, desc=desc)
        return
    if k=='callstmt':
        _eval_multi(interp, st.expr); return
    if k=='function':
        # shouldn't happen as transformed
        return
    raise Exception(f"unknown stmt {k}")

_sentinel=object()
Interp.exec_block=_exec_block
Interp.eval_single=_eval_single

