# ----- arg helpers -----
def arg(args,i):
    return args[i-1] if 1<=i<=len(args) else None
def got_name(v, present=True):
    if not present: return "no value"
    return lua_type(v)
def check_string(interp, args, i):
    v=arg(args,i)
    if isinstance(v, bytes): return v
    if is_num(v): return fmt_num(v).encode()
    interp.arg_error(i, f"(string expected, got {got_name(v, i<=len(args))})".encode())
def opt_string(interp, args, i, default):
    v=arg(args,i)
    if v is None: return default
    return check_string(interp, args, i)
def check_number(interp, args, i):
    v=arg(args,i)
    n=to_lua_num(v)
    if n is not None: return n
    interp.arg_error(i, f"(number expected, got {got_name(v, i<=len(args))})".encode())
def opt_number(interp, args, i, default):
    v=arg(args,i)
    if v is None: return default
    return check_number(interp, args, i)
def check_int(interp, args, i):
    n=check_number(interp, args, i)
    return int(n)  # trunc toward zero in python for float int()
def opt_int(interp, args, i, default):
    v=arg(args,i)
    if v is None: return default
    return check_int(interp, args, i)
def check_table(interp, args, i):
    v=arg(args,i)
    if isinstance(v, LuaTable): return v
    interp.arg_error(i, f"(table expected, got {got_name(v, i<=len(args))})".encode())
def opt_table(interp, args, i, default=None):
    v=arg(args,i)
    if v is None: return default
    return check_table(interp,args,i)
def check_function(interp, args, i):
    v=arg(args,i)
    if isinstance(v,(LuaFunction,BuiltinFunction)): return v
    interp.arg_error(i, f"(function expected, got {got_name(v, i<=len(args))})".encode())
def check_any(interp, args, i):
    if i>len(args): interp.arg_error(i, b"(value expected)")
    return args[i-1]
def bool_arg(args,i,default=False):
    v=arg(args,i)
    if v is None: return default
    return not (v is None or v is False)

def lua_tostring_for_print(interp, v):
    # tostring builtin semantics: respects __tostring, else default; for numbers etc.
    return interp.tostring_value(v, use_meta=True)

# ----- Lua pattern matching -----
# operates on bytes
def _class_match(c, cl):
    # c int byte, cl byte char (lowercase letter)
    ch=chr(cl) if isinstance(cl,int) else cl
    low=ch.lower()
    res=False
    b=c
    if low=='a': res= (65<=b<=90 or 97<=b<=122)
    elif low=='c': res= b<32 or b==127
    elif low=='d': res= 48<=b<=57
    elif low=='g': res= 33<=b<=126
    elif low=='l': res= 97<=b<=122
    elif low=='p': res= (33<=b<=47 or 58<=b<=64 or 91<=b<=96 or 123<=b<=126)
    elif low=='s': res= b in (32,9,10,11,12,13)
    elif low=='u': res= 65<=b<=90
    elif low=='w': res= (48<=b<=57 or 65<=b<=90 or 97<=b<=122)
    elif low=='x': res= (48<=b<=57 or 65<=b<=70 or 97<=b<=102)
    elif low=='z': res= b==0
    else: res= (b==cl)
    if ch.isupper(): res=not res
    return res

class PatternError(Exception): pass

class Patt:
    def __init__(self, pat_bytes):
        self.p=pat_bytes  # bytes
    # parsing helpers at match time index based
    def char_class_end(self, i):
        # i points at '%', return index after class/set
        p=self.p
        if i>=len(p): raise PatternError("malformed pattern (ends with '%')")
        # Actually caller ensures
        i+=1
        if i>=len(p): raise PatternError("malformed pattern (ends with '%')")
        if p[i:i+1]==b'b': # %b handled elsewhere
            return i+3  # % b x y ? caller checks
        if p[i:i+1]==b'f': # %f[set]
            # next must be [
            j=i+1
            if j>=len(p) or p[j:j+1]!=b'[': raise PatternError("missing '[' after '%f' in pattern")
            return self.set_end(j)
        return i+1
    def set_end(self, i):
        # i at '[' return index after ']'
        p=self.p
        i+=1
        if i<len(p) and p[i:i+1]==b'^': i+=1
        first=True
        while i<len(p):
            c=p[i:i+1]
            if c==b'%':
                i+=2; first=False; continue
            if c==b']' and not first:
                return i+1
            first=False; i+=1
        raise PatternError("malformed pattern (missing ']')")
    def match_set(self, c, i, j):
        # set from i '[' to j-1 ']'
        p=self.p
        i+=1
        negate=False
        if i<j-1 and p[i:i+1]==b'^': negate=True; i+=1
        res=False
        first=True
        k=i
        end=j-1
        while k<end:
            cc=p[k:k+1]
            if cc==b'%':
                if k+1<end:
                    cl=p[k+1]
                    if _class_match(c, cl): res=True
                    k+=2; first=False; continue
                else: k+=1; continue
            elif k+2<end and p[k+1:k+2]==b'-':
                lo=p[k]; hi=p[k+2]
                if lo<=c<=hi: res=True
                k+=3; first=False; continue
            else:
                if p[k]==c: res=True
                k+=1; first=False; continue
        return (not res) if negate else res
    def single_match(self, s, si, pi, pj):
        # does s[si] match pattern piece p[pi:pj] (single char item)
        if si>=len(s): return False
        c=s[si]; p=self.p
        pc=p[pi:pi+1]
        if pc==b'.': return True
        if pc==b'%':
            if pi+1>=pj: return False
            return _class_match(c, p[pi+1])
        if pc==b'[':
            return self.match_set(c, pi, pj)
        return c==p[pi]
    def match_b(self, s, si, pi):
        # %bxy pi at %, returns new si or None
        p=self.p
        if pi+3>len(p): raise PatternError("malformed pattern (missing arguments to '%b')")
        x=p[pi+2]; y=p[pi+3]
        if si>=len(s) or s[si]!=x: return None
        cnt=1; i=si+1
        while i<len(s):
            if s[i]==y:
                cnt-=1
                if cnt==0: return i+1
            elif s[i]==x: cnt+=1
            i+=1
        return None
    def match(self, s, si, pi, captures):
        # captures list of (start, len or -1 unfinished, -2 position)
        # returns si end or None, using recursion/backtracking
        p=self.p
        while pi < len(p):
            pc=p[pi:pi+1]
            if pc==b'(':
                # capture start
                if pi+1<len(p) and p[pi+1:pi+2]==b')':
                    # position capture
                    captures.append([si, -2])
                    r=self.match(s, si, pi+2, captures)
                    if r is not None: return r
                    captures.pop(); return None
                else:
                    captures.append([si, -1])
                    idx=len(captures)-1
                    r=self.match(s, si, pi+1, captures)
                    if r is not None: return r
                    # remove this capture
                    del captures[idx:]; return None
            if pc==b')':
                # close capture: find last unfinished
                for idx in range(len(captures)-1,-1,-1):
                    if captures[idx][1]==-1:
                        captures[idx][1]=si-captures[idx][0]
                        r=self.match(s, si, pi+1, captures)
                        if r is not None: return r
                        captures[idx][1]=-1; return None
                raise PatternError("invalid pattern capture")
            if pc==b'$' and pi==len(p)-1:
                return si if si==len(s) else None
            if pc==b'%':
                if pi+1<len(p) and p[pi+1:pi+2]==b'b':
                    nb=self.match_b(s, si, pi)
                    if nb is None: return None
                    si=nb; pi+=4; continue
                if pi+1<len(p) and p[pi+1:pi+2]==b'f':
                    # frontier: next char in set, prev not
                    # %f[set]
                    j=self.set_end(pi+2)
                    in_cur = (si < len(s) and self.match_set(s[si], pi+2, j)) if True else False
                    # need handle si==len: treat as \0 not in set
                    if si>=len(s):
                        cur_in=False
                    else:
                        cur_in=self.match_set(s[si], pi+2, j)
                    if si<=0: prev_in=False
                    else: prev_in=self.match_set(s[si-1], pi+2, j)
                    if (not prev_in) and cur_in:
                        pi=j; continue
                    else: return None
                if pi+1<len(p) and p[pi+1].__class__ is int and 49 <= p[pi+1] <= 57:
                    # back reference as single item?
                    idx=p[pi+1]-49
                    if idx>=len(captures) or captures[idx][1]<0: raise PatternError("invalid capture index")
                    st,ln=captures[idx]
                    if s[si:si+ln]==s[st:st+ln]:
                        # backref is not quantifiable in Lua? It is a pattern item...
                        # check quantifier after?
                        # Simplify treat as consumed, but quantifier not expected
                        si+=ln; pi+=2; continue
                    else: return None
                # single class item with possible quantifier
                pj=pi+2
                return self._match_single_quant(s, si, pi, pj, captures)
            if pc==b'[':
                pj=self.set_end(pi)
                return self._match_single_quant(s, si, pi, pj, captures)
            # regular char or .
            pj=pi+1
            return self._match_single_quant(s, si, pi, pj, captures)
        return si
    def _match_single_quant(self, s, si, pi, pj, captures):
        p=self.p
        if pj < len(p) and p[pj:pj+1] in (b'*',b'+',b'-',b'?'):
            q=p[pj:pj+1]
            if q==b'?':
                # try with, then without
                if self.single_match(s, si, pi, pj):
                    r=self.match(s, si+1, pj+1, captures[:]) # need capture copy semantics messy
                    # Our match mutates captures; above used copy attempt but self.match expects same list...
                    # Reimplement with original approach: try greedy with snapshot
                    # Restore: this branch not reached because we passed copy? Actually r computed with copy list object, original captures not mutated except... we passed captures[:] shallow, inner appends affect copy.
                    if r is not None:
                        # merge copy? captures were shallow copies entries shared lists. For simplicity redo properly below
                        pass
                    # Fall through to proper implementation below
                # Proper
                # save state
                saved=[c[:] for c in captures]
                if self.single_match(s, si, pi, pj):
                    r=self.match(s, si+1, pj+1, captures)
                    if r is not None: return r
                    # restore
                    captures[:]=[c[:] for c in saved]
                return self.match(s, si, pj+1, captures)
            if q==b'*' or q==b'+':
                # greedy max
                cnt=0
                while self.single_match(s, si+cnt, pi, pj): cnt+=1
                mincnt=0 if q==b'*' else 1
                saved=[c[:] for c in captures]
                for take in range(cnt, mincnt-1, -1):
                    captures[:]=[c[:] for c in saved]
                    r=self.match(s, si+take, pj+1, captures)
                    if r is not None: return r
                captures[:]=[c[:] for c in saved]
                return None
            if q==b'-':
                # lazy
                saved=[c[:] for c in captures]
                take=0
                while True:
                    captures[:]=[c[:] for c in saved]
                    r=self.match(s, si+take, pj+1, captures)
                    if r is not None: return r
                    if self.single_match(s, si+take, pi, pj): take+=1; continue
                    break
                captures[:]=[c[:] for c in saved]
                return None
        else:
            if self.single_match(s, si, pi, pj):
                return self.match(s, si+1, pj, captures)
            return None

def lua_pattern_find(interp, s, pat, init=0, plain=False):
    # returns for find/match usage internal
    n=len(s)
    if init>=0:
        start=init if init<=n else None
        if init>n: return None
    else:
        start=max(n+init,0) if False else (n+init if n+init>=0 else 0)
        # Lua: init negative count from end, clamp 0
        start = n+init
        if start<0: start=0
    if plain:
        idx=s.find(pat, start)
        if idx==-1: return None
        return (idx, idx+len(pat)-1, [])
    anchored=False
    pat2=pat
    if pat2.startswith(b'^'):
        anchored=True; pat2=pat2[1:]
    pobj=Patt(pat2)
    # validate pattern? Trigger parsing errors even if no match: Lua checks pattern.
    # Attempt to match at positions
    positions=[start] if anchored else range(start, n+1)
    for st in positions:
        caps=[]
        try:
            end=pobj.match(s, st, 0, caps)
        except PatternError as e:
            interp.error_str(str(e).encode())
        if end is not None:
            # check unfinished captures
            for c in caps:
                if c[1]==-1: interp.error_str(b"unfinished capture")
            return (st, end-1, caps)
    return None

def captures_to_values(s, caps, whole_start, whole_end):
    vals=[]
    for st,ln in caps:
        if ln==-2: vals.append(float(st+1))
        else: vals.append(s[st:st+ln])
    return vals

