# ----- compilation helpers -----
def compute_chunk_display(chunkname, src):
    if chunkname is None:
        # [string "..."] first line truncated
        first=src.split(b'\n',1)[0][:45]
        # Lua truncates: if longer, ... ?
        return b'[string "' + first + b'"]'
    if isinstance(chunkname, str): chunkname=S(chunkname)
    if chunkname.startswith(b'@') or chunkname.startswith(b'='):
        return chunkname[1:]
    # Lua treats other as string chunk name, display [string "name"]
    # However internal callers pass display names starting with '(' or plain file names via @.
    return chunkname

def attach_chunk_to_proto(node, chunk_display, chunkname):
    # walk nodes
    seen=set()
    def walk(n):
        if id(n) in seen: return
        seen.add(id(n))
        if isinstance(n, Node):
            if n.kind=='function':
                n.proto.chunk_display=chunk_display; n.proto.chunkname=chunkname
            for v in n.__dict__.values(): walk(v)
        elif isinstance(n, (list,tuple)):
            for v in n: walk(v)
        elif isinstance(n, dict):
            for v in n.values(): walk(v)
    walk(node)

def compile_source(interp, src, chunkname, mode=None, env=None):
    # returns function or (None, errmsg bytes)
    if src is None: src=b''
    if isinstance(src, str): src=S(src)
    is_byte=False
    if src.startswith(b'\x1b'):
        is_byte=True
        # our dump
        if src.startswith(b'\x1bLJ'):
            # try decode our payload
            fn=decode_dump(interp, src)
            if fn is not None:
                if env is not None and isinstance(fn, LuaFunction): fn.env=env
                return fn
            # foreign bytecode: LuaJIT would load LJ bytecode if valid; our dumps have marker handled.
            # If marker not ours, treat as bytecode error
            if mode and 't' in mode and 'b' not in mode:
                return (None, b"attempt to load a binary chunk (mode is 't')" if False else b"attempt to load a binary chunk")
            return (None, b"bad bytecode")
        else:
            return (None, b"bad bytecode")
    if mode:
        mode_str=mode.decode() if isinstance(mode,bytes) else str(mode)
        if 'b' in mode_str and 't' not in mode_str:
            return (None, b"attempt to load a text chunk (mode is 'b')")
        # mode t and text ok
    chunk_display=compute_chunk_display(chunkname, src)
    if chunkname is None: chunkname_bytes=b'chunk'
    elif isinstance(chunkname,str): chunkname_bytes=S(chunkname)
    else: chunkname_bytes=chunkname
    try:
        parser=Parser(src, chunk_display, chunkname_bytes)
        proto=parser.parse()
    except SyntaxErr as e:
        return (None, e.full())
    proto.chunk_display=chunk_display; proto.chunkname=chunkname_bytes
    attach_chunk_to_proto(proto, chunk_display, chunkname_bytes)
    fn=LuaFunction(proto, env if env is not None else interp.globals, [])
    return fn

def encode_value_for_dump(interp, v, seen=None):
    raise Exception("not used")

def make_dump_bytes(interp, fn):
    # serialize proto and upcells
    import pickle
    payload={}
    if isinstance(fn, LuaFunction):
        payload['proto']=fn.proto
        # captured scopes: list of dict name->Cell, serialize cell values
        caps=[]
        for scope in fn.upcells:
            caps.append({k: cell.value for k,cell in scope.items()})
        payload['caps']=caps
    else:
        payload['proto']=None
    try:
        data=pickle.dumps(payload, protocol=4)
    except Exception as e:
        data=b''
    return b'\x1bLJ\x02\x08PYDUMP1\n' + data

def decode_dump(interp, src):
    marker=b'PYDUMP1\n'
    idx=src.find(marker)
    if idx==-1: return None
    import pickle
    try:
        payload=pickle.loads(src[idx+len(marker):])
    except Exception:
        return None
    proto=payload.get('proto')
    if proto is None: return None
    caps=[]
    for scope in payload.get('caps',[]):
        caps.append({k: Cell(v) for k,v in scope.items()})
    return LuaFunction(proto, interp.globals, caps)

