            # foreign bytecode: LuaJIT would load LJ bytecode if valid; our dumps have marker handled.
            # If marker not ours, treat as bytecode error
            if mode and 't' in mode and 'b' not in mode:
                return (None, b"attempt to load a binary chunk (mode is 't')" if False else b"attempt to load a binary chunk")
            return (None, b"bad bytecode")
        else:
            return (None, b"bad bytecode")
