    raise Exception("not used")

def make_dump_bytes(interp, fn):
    # serialize proto and upcells
    import pickle
    payload={}
    if isinstance(fn, LuaFunction):
        payload['proto']=fn.proto
        # captured scopes: list of dict name->Cell, serialize cell values
        caps=[]
        for scope in fn.upcells:
            caps.append({k: cell.value for k,cell in scope.items()})
        payload['caps']=caps
    else:
        payload['proto']=None
    try:
        data=pickle.dumps(payload, protocol=4)
    except Exception as e:
        data=b''
    return b'\x1bLJ\x02\x08PYDUMP1\n' + data

def decode_dump(interp, src):
    marker=b'PYDUMP1\n'
    idx=src.find(marker)
    if idx==-1: return None
    import pickle
    try:
        payload=pickle.loads(src[idx+len(marker):])
    except Exception:
        return None
    proto=payload.get('proto')
    if proto is None: return None
    caps=[]
    for scope in payload.get('caps',[]):
        caps.append({k: Cell(v) for k,v in scope.items()})
    return LuaFunction(proto, interp.globals, caps)

