    f=fo.f
    if not formats: formats=[b'*l']
    results=[]
    for fmt in formats:
        if is_num(fmt):
            cnt=int(float(fmt))
            if cnt==0:
                # peek EOF
                c=f.read(1)
                if not c: results.append(None)
                else:
                    try: f.seek(-1,1)
                    except Exception: pass
                    results.append(b'')
                continue
            data=f.read(cnt)
            if not data: results.append(None)
            else: results.append(data)
