            data=f.read() or b''; results.append(data)
        elif fs in (b'*l',b'l'):
            line=f.readline()
            if not line: results.append(None)
            else:
                if line.endswith(b'\n'):
                    line=line[:-1]
                    if line.endswith(b'\r'): line=line[:-1]
                results.append(line)
