# ----- coroutine -----
def coro_entry(interp, coro, first_args):
    interp.tls.thread_obj=coro
    interp.tls.stack=[]
    coro.py_thread_id=threading.get_ident()
    try:
        res=interp.call_value(coro.func, list(first_args))
        coro.yield_vals=('return', res)
    except LuaError as e:
        coro.yield_vals=('error', e.value)
    except OsExitExc:
        raise
    except Exception as e:
        coro.yield_vals=('error', S(str(e)))
    coro.status='dead'
    coro.yield_ev.set()

