    f=check_any(interp,args,1)
    if not callable_lua(interp,f): interp.arg_error(1, f"(function expected, got {lua_type(f)})".encode())
    return [LuaThread(func=f)]
def coro_resume_impl(interp, coro, args):
    if coro.status=='dead': return [False, b'cannot resume dead coroutine']
    if coro.status=='running': return [False, b'cannot resume non-suspended coroutine']
    if coro.status=='normal': return [False, b'cannot resume normal coroutine']
    caller=interp.get_thread_obj()
    # switch
    coro.yield_ev.clear()
    if not coro.started:
        coro.started=True; coro.status='running'
        if caller is not coro: caller_status_old=caller.status; caller.status='normal' if caller is not interp.main_thread else caller.status
        t=threading.Thread(target=coro_entry, args=(interp,coro,list(args)), daemon=True)
        coro.thread=t; t.start()
        coro.yield_ev.wait()
        if caller is not interp.main_thread: caller.status='running'
        kind, vals = coro.yield_vals if coro.yield_vals else ('error', b'dead')
        if coro.status!='dead': coro.status='suspended' if kind=='yield' else coro.status
        if kind=='return': coro.status='dead'; return [True]+list(vals)
        if kind=='error': coro.status='dead'; return [False, vals]
        return [True]+list(vals)
    else:
        # resuming suspended
        coro.resume_vals=list(args); coro.status='running'
        if caller is not interp.main_thread: caller.status='normal'
        coro.resume_ev.set()
        coro.yield_ev.wait()
        if caller is not interp.main_thread: caller.status='running'
        kind, vals = coro.yield_vals if coro.yield_vals else ('error', b'dead')
        if kind=='return': coro.status='dead'; return [True]+list(vals)
        if kind=='error': coro.status='dead'; return [False, vals]
        coro.status='suspended'
        return [True]+list(vals)
