# ----- coroutine -----
def coro_entry(interp, coro, first_args):
    interp.tls.thread_obj=coro
    interp.tls.stack=[]
    coro.py_thread_id=threading.get_ident()
    try:
        res=interp.call_value(coro.func, list(first_args))
        coro.yield_vals=('return', res)
    except LuaError as e:
        coro.yield_vals=('error', e.value)
    except OsExitExc:
        raise
    except Exception as e:
        coro.yield_vals=('error', S(str(e)))
    coro.status='dead'
    coro.yield_ev.set()

def bf_coro_create(interp,args):
    f=check_any(interp,args,1)
    if not callable_lua(interp,f): interp.arg_error(1, f"(function expected, got {lua_type(f)})".encode())
    return [LuaThread(func=f)]
def coro_resume_impl(interp, coro, args):
    if coro.status=='dead': return [False, b'cannot resume dead coroutine']
    if coro.status=='running': return [False, b'cannot resume non-suspended coroutine']
    if coro.status=='normal': return [False, b'cannot resume normal coroutine']
    caller=interp.get_thread_obj()
    # switch
    coro.yield_ev.clear()
    if not coro.started:
        coro.started=True; coro.status='running'
        if caller is not coro: caller_status_old=caller.status; caller.status='normal' if caller is not interp.main_thread else caller.status
        t=threading.Thread(target=coro_entry, args=(interp,coro,list(args)), daemon=True)
        coro.thread=t; t.start()
        coro.yield_ev.wait()
        if caller is not interp.main_thread: caller.status='running'
        kind, vals = coro.yield_vals if coro.yield_vals else ('error', b'dead')
        if coro.status!='dead': coro.status='suspended' if kind=='yield' else coro.status
        if kind=='return': coro.status='dead'; return [True]+list(vals)
        if kind=='error': coro.status='dead'; return [False, vals]
        return [True]+list(vals)
    else:
        # resuming suspended
        coro.resume_vals=list(args); coro.status='running'
        if caller is not interp.main_thread: caller.status='normal'
        coro.resume_ev.set()
        coro.yield_ev.wait()
        if caller is not interp.main_thread: caller.status='running'
        kind, vals = coro.yield_vals if coro.yield_vals else ('error', b'dead')
        if kind=='return': coro.status='dead'; return [True]+list(vals)
        if kind=='error': coro.status='dead'; return [False, vals]
        coro.status='suspended'
        return [True]+list(vals)
def bf_coro_resume(interp,args):
    co=check_any(interp,args,1)
    if not isinstance(co, LuaThread): interp.arg_error(1, f"(coroutine expected, got {lua_type(co)})".encode())
    return coro_resume_impl(interp, co, list(args[1:]))
def bf_coro_yield(interp,args):
    co=interp.get_thread_obj()
    if co is interp.main_thread or co is None:
        interp.error_str(b"attempt to yield from outside a coroutine")
    co.yield_vals=('yield', list(args))
    co.status='suspended'
    co.resume_ev.clear()
    co.yield_ev.set()
    co.resume_ev.wait()
    co.status='running'
    vals=co.resume_vals or []
    co.resume_vals=None
    return list(vals)
def bf_coro_status(interp,args):
    co=check_any(interp,args,1)
    if not isinstance(co,LuaThread): interp.arg_error(1, f"(coroutine expected, got {lua_type(co)})".encode())
    cur=interp.get_thread_obj()
    if co is cur: return [b'running']
    return [S(co.status)]
def bf_coro_running(interp,args):
    co=interp.get_thread_obj()
    if co is interp.main_thread: return [None]
    return [co]
def bf_coro_isyieldable(interp,args):
    co=interp.get_thread_obj()
    return [co is not interp.main_thread]
def bf_coro_wrap(interp,args):
    co=bf_coro_create(interp,args)[0]
    def wrapper(interp2, wargs):
        res=coro_resume_impl(interp2, co, list(wargs))
        if res and res[0] is True: return list(res[1:])
        # error
        e=LuaError(res[1] if len(res)>1 else b'error in coroutine'); e.stack_snapshot=interp2.snapshot_stack(); raise e
    fn=BuiltinFunction(wrapper, name=None); fn.addr=new_addr(); return [fn]

