# ----- bit lib -----
def tobit32(x):
    x=int(x)&0xffffffff
    return x-0x100000000 if x>=0x80000000 else x
def bit_num(interp,args,i):
    n=to_lua_num(arg(args,i))
    if n is None: interp.arg_error(i, f"(number expected, got {got_name(arg(args,i), i<=len(args))})".encode())
    return n
def bf_bit_tobit(interp,args): return [float(tobit32(int(bit_num(interp,args,1))))]
def bf_bit_bnot(interp,args): return [float(tobit32(~int(bit_num(interp,args,1))))]
def make_bit_fold(opname):
    def f(interp,args):
        if not args: interp.arg_error(1,b"(number expected, got no value)")
        vals=[int(bit_num(interp,args,i)) for i in range(1,len(args)+1)]
        if opname=='band':
            r=vals[0]
            for v in vals[1:]: r&=v
        elif opname=='bor':
            r=vals[0]
            for v in vals[1:]: r|=v
        else:
            r=vals[0]
            for v in vals[1:]: r^=v
        return [float(tobit32(r))]
    return f
def bf_bit_bswap(interp,args):
    x=int(bit_num(interp,args,1))&0xffffffff
    r=((x&0xff)<<24)|((x&0xff00)<<8)|((x>>8)&0xff00)|((x>>24)&0xff)
    return [float(tobit32(r))]
def shift_amount(interp,args,i=2):
    n=bit_num(interp,args,i); return int(n)
def bf_bit_lshift(interp,args):
    x=int(bit_num(interp,args,1))&0xffffffff; s=shift_amount(interp,args)
    if s>=0: r=0 if s>=32 else (x<<s)&0xffffffff
    else: r=0 if -s>=32 else x>>(-s)
    return [float(tobit32(r))]
def bf_bit_rshift(interp,args):
    x=int(bit_num(interp,args,1))&0xffffffff; s=shift_amount(interp,args)
    if s>=0: r=0 if s>=32 else x>>s
    else: r=0 if -s>=32 else (x<<(-s))&0xffffffff
    return [float(tobit32(r))]
def bf_bit_arshift(interp,args):
    x=tobit32(int(bit_num(interp,args,1))); s=shift_amount(interp,args)
    if s>=0: r= -1 if (x<0 and s>=31) else (x>>min(s,31) if s<32 else (-1 if x<0 else 0))
    else: r=0 if -s>=32 else tobit32((x&0xffffffff)<<(-s))
    return [float(tobit32(r))]
def bf_bit_rol(interp,args):
    x=int(bit_num(interp,args,1))&0xffffffff; s=shift_amount(interp,args)%32
    r=((x<<s)|(x>>(32-s) if s else x))&0xffffffff if s else x
    if s: r=((x<<s)&0xffffffff)|(x>>(32-s))
    return [float(tobit32(r))]
def bf_bit_ror(interp,args):
    x=int(bit_num(interp,args,1))&0xffffffff; s=shift_amount(interp,args)%32
    r=((x>>s)|(x<<(32-s) if s else x))&0xffffffff if s else x
    if s: r=(x>>s)|((x<<(32-s))&0xffffffff)
    return [float(tobit32(r))]
def bf_bit_tohex(interp,args):
    x=int(bit_num(interp,args,1))&0xffffffff; n=opt_int(interp,args,2,8)
    upper=False
    if n<0: upper=True; n=-n
    if n>8: 
        # BitOp: n can be >8? It formats with leading? For 32-bit, if n>8 maybe ... use n width with x value
        s=('%0*x' % (n, x)) if not upper else ('%0*X' % (n,x))
        return [S(s)]
    # take low n digits
    mask=(1<<(4*n))-1 if n<8 else 0xffffffff
    xv=x&mask
    s=('%0*x' % (n, xv)) if n>0 else ''
    if upper: s=s.upper()
    return [S(s)]

