                if a=='-j': cmd=args_all[i+1]; i+=2
                else: cmd=a[2:]; i+=1
                if do_jit_command_cli(interp,cmd)!=0: return 1
                continue
            elif a in ('-v','-i','-E'):
                i+=1; continue
            elif a=='--':
                break
            else:
                i+=1; continue
        if b_idx is not None:
            # process preceding Os already done; -b always fails due missing module
            sys.stderr.buffer.write(S(prog)+b": unknown luaJIT command or jit.* modules not installed\n"); return 1
        # script execution
        if script_idx is not None and script_idx < len(args_all):
            script=args_all[script_idx]; script_args=[S(x) for x in args_all[script_idx+1:]]
            if script=='-':
                src=sys.stdin.buffer.read()
                rc=run_source_string(interp, src, b'stdin', script_args)
                if rc!=0: return rc
            else:
                try:
                    with open(script,'rb') as f: src=f.read()
                except OSError as e:
                    sys.stderr.buffer.write(S(prog)+b": cannot open "+S(script)+b": "+os.strerror(e.errno).encode()+b"\n"); return 1
                rc=run_source_string(interp, src, b'@'+S(script), script_args)
                if rc!=0: return rc
            if has_i:
                return interactive_loop(interp)
            return 0
        # no script
        if has_i:
            return interactive_loop(interp)
        if has_v:
            return 0
        if has_e:
            return 0
        # has_l, -j, -O etc do not prevent stdin
        # stdin tty?
        if sys.stdin.isatty():
            # banner if not already printed (has_i false, has_v false)
            if not (has_v or has_i): write_stdout(interp,S(VERSION)+b'\n')
            return interactive_loop(interp)
        else:
            src=sys.stdin.buffer.read()
            if src:
                rc=run_source_string(interp, src, b'stdin', [])
                if rc!=0: return rc
            return 0
    except OsExitExc as e:
        try: sys.stdout.buffer.flush()
        except Exception: pass
        return e.code
    except KeyboardInterrupt:
        return 1

if __name__=='__main__':
    try:
        code=main(sys.argv)
    except OsExitExc as e:
        code=e.code
    except BrokenPipeError:
        code=1
    sys.stdout.flush() if not sys.stdout.closed else None
    sys.exit(code if isinstance(code,int) else 0)
