# Re-define FFI cdata printing (used via cdata_tostring stub)
def ffi_cdata_tostring(interp,v):
    ct=v.ctype
    if ct.kind=='ctype':
        return b"ctype<"+v.value.display().encode()+b">" if isinstance(v.value,CType) else b"ctype<?>"
    if ct.kind=='primitive':
        cat=PRIM_CAT.get(ct.name,'int')
        if cat=='int' and ct.size==8:
            return str(v.value).encode()+(b'ULL' if not ct.signed else b'LL')
        if cat=='complex':
            return fmt_num(v.value.real).encode()+(b"+"+fmt_num(v.value.imag).encode()+b"i" if v.value.imag>=0 else fmt_num(v.value.imag).encode()+b"i")
        return b"cdata<"+ct.display().encode()+b">: 0x"+format(v.addr,'x').encode()
    if ct.kind=='enum': return fmt_num(float(v.value)).encode()
    return b"cdata<"+ct.display().encode()+b">: 0x"+format(v.addr,'x').encode()
