    try: interp.gc_pending.append((gcfunc,shadow))
    except Exception: pass
def schedule_gc_for_userdata(interp, ud):
    if not isinstance(ud, LuaUserdata): return
    mt=ud.metatable
    if not isinstance(mt,LuaTable): return
    gcfunc=mt.rawget(b'__gc')
    if gcfunc is None or not callable_lua(interp,gcfunc): return
    if not hasattr(interp,'gc_scheduled'): interp.gc_scheduled={}
    if id(ud) in interp.gc_scheduled: return
    if not hasattr(interp,'gc_pending'): interp.gc_pending=[]
    shadow=LuaUserdata(ud.data, kind=ud.kind); shadow.addr=ud.addr; shadow.metatable=mt; shadow.env=ud.env; shadow.tostring_override=ud.tostring_override
    fin=weakref.finalize(ud, _queue_gc_callback, interp, gcfunc, shadow); fin.atexit=False
    interp.gc_scheduled[id(ud)]=fin
def track_userdata_mt(interp, ud):
    if not isinstance(ud,LuaUserdata): return
    if not hasattr(interp,'ud_by_mt'): interp.ud_by_mt={}
    mt=ud.metatable
    if isinstance(mt,LuaTable):
        interp.ud_by_mt.setdefault(id(mt),[]).append(weakref.ref(ud))
    schedule_gc_for_userdata(interp,ud)
def note_gc_field_set(interp, tbl):
    if not hasattr(interp,'ud_by_mt'): return
    lst=interp.ud_by_mt.get(id(tbl),[])
    for ref in list(lst):
        ud=ref()
        if ud is not None: schedule_gc_for_userdata(interp,ud)
def run_pending_gc(interp):
    if not hasattr(interp,'gc_pending'): return
    pending=list(interp.gc_pending); interp.gc_pending=[]
    for gcfunc,shadow in pending:
        try: interp.call_value(gcfunc,[shadow])
        except Exception: pass

'''
